(* [comment removed for export] *)
Definition g14f1_exit (sp gp tp t1 t4 t5 t6 s0 s1 a2 a4 a6 s2 s3 s4 s5 s6 s7 s8 s9 s10 t3 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (DR dn : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t2' a0' a1' a3' a5' a7' s11' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp s11' t1 s6 s0 s1 a0' a1' a3' t3 a4 a5' a6 t0' s2 t4 t2' s3 s10 s7 s4 s9 s5 a2 s8 a7' t5 t6)
             F (Z_to_bv 64 0x137d28) fc None m' (seg_rom asegs)
    /\ munch [(DR, DR + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma g14f1_rows : forall (k : nat) (i : Z)
    (gp tp t2 a1 a3 a4 a5 a6 s0 s2 s10 t3 t5 c31 : word) F fc (m : mem)
    (FP dh swpl dwpl PS1 PD1 SR sn DR dn fs9 fs4 sh rsh : Z),
  Z.of_nat k = dh - i -> 0 <= i -> (1 <= k)%nat -> dh <= 20000 ->
  0 < swpl <= 2^24 -> 0 < dwpl <= 2^24 -> swpl * dh <= 2^24 -> dwpl * dh <= 2^24 ->
  0 < SR -> SR mod 4 = 0 -> SR + sn <= 2^47 -> 0 < DR -> DR mod 4 = 0 -> DR + dn <= 2^47 -> PS1 mod 4 = 0 -> PD1 mod 4 = 0 ->
  (DR + dn <= 0x7fff7000 \/ 0x10007fff8000 <= DR) ->
  0 < FP -> FP mod 16 = 0 -> FP + 256 <= 2^47 -> (DR + dn <= FP \/ FP + 256 <= DR) ->
  0 <= fs9 < 2 -> 0 <= fs4 < 2 -> 0 <= sh < 32 -> 0 <= rsh < 32 ->
  (forall i', 0 <= i' <= dh -> SR <= PS1 + 4 * (swpl * i') /\ PS1 + 4 * (swpl * i') + 4 <= SR + sn + 4 * swpl) ->
