Definition g14w2_rows_exit (sp gp tp t0 t1 s0 s1 a3 a7 s2 s6 s10 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (DR dn : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' t2' a0' a1' a2' a4' a5' a6' s3' s4' s5' s7' s8' s9' s11' : word) (m' : mem),
    ms' = MS (mkR s9' sp gp tp s4' t1 t0 s0 s1 a0' a1' t3 a3 a4' ra' a6' t4 s2 a7 t2' s3' a5' s5' s7' a2' s10 s11' s8' s6 t5 t6)
             F (Z_to_bv 64 0x137f00) fc None m' (seg_rom asegs)
    /\ munch [(DR, DR + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma g14w2_rows : forall (k : nat) (i : Z)
    (ra gp tp t2 s0 a0 a3 a5 s2 s3 s4 s5 s7 s8 s9 t5 w104 : word) F fc (m : mem)
    (FP dh n swpl dwpl PSF PDF SR sn DR dn sh rsh : Z),
  Z.of_nat k = dh - i -> 0 <= i -> (1 <= k)%nat -> dh <= 20000 -> 1 <= n < 2^26 ->
  0 < swpl <= 2^24 -> 0 < dwpl <= 2^24 -> swpl * dh <= 2^24 -> dwpl * dh <= 2^24 ->
  0 < SR -> SR mod 4 = 0 -> SR + sn <= 2^47 -> 0 < DR -> DR mod 4 = 0 -> DR + dn <= 2^47 -> PSF mod 4 = 0 -> PDF mod 4 = 0 ->
  (DR + dn <= 0x7fff7000 \/ 0x10007fff8000 <= DR) ->
  0 < FP -> FP mod 16 = 0 -> FP + 256 <= 2^47 -> (DR + dn <= FP \/ FP + 256 <= DR) ->
  0 <= sh < 32 -> 0 <= rsh < 32 ->
  (forall i', 0 <= i' < dh -> SR <= PSF + 4 * (swpl * i') /\ PSF + 4 * (swpl * i') + 4 * (n + 1) <= SR + sn) ->
  (forall i', 0 <= i' < dh -> DR <= PDF + 4 * (dwpl * i') /\ PDF + 4 * (dwpl * i') + 4 * n <= DR + dn) ->
  rw_cells asegs m (FP + 96) [C8 (Z_to_bv 64 dh); C8 w104; C8 (Z_to_bv 64 n); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 1); C8 (Z_to_bv 64 1)] ->
  wr_at asegs m SR sn -> acc asegs m SR sn -> wr_at asegs m DR dn -> acc asegs m DR dn -> mem_inv asegs m ->
  evt asegs (g14w2_rows_exit (Z_to_bv 64 FP) gp tp (Z_to_bv 64 (swpl * 4)) (Z_to_bv 64 2147450880) s0 (Z_to_bv 64 rsh) a3 (Z_to_bv 64 (dwpl * 4)) s2
               (Z_to_bv 64 (-5)) (Z_to_bv 64 31) (Z_to_bv 64 (n * 4)) (Z_to_bv 64 32) t5 (Z_to_bv 64 sh) F fc m DR dn)
    (MS (mkR s9 (Z_to_bv 64 FP) gp tp s4 (Z_to_bv 64 2147450880) (Z_to_bv 64 (swpl * 4)) s0 (Z_to_bv 64 rsh) a0 (Z_to_bv 64 i) (Z_to_bv 64 (n * 4)) a3 (Z_to_bv 64 (PDF + 4 * (dwpl * i))) ra (Z_to_bv 64 (PSF + 4 * (swpl * i))) (Z_to_bv 64 32) s2 (Z_to_bv 64 (dwpl * 4)) t2 s3 a5 s5 s7 (Z_to_bv 64 (PDF + 4 * (dwpl * i))) (Z_to_bv 64 31) (Z_to_bv 64 (PSF + 4 * (swpl * i))) s8 (Z_to_bv 64 (-5)) t5 (Z_to_bv 64 sh))
        F (Z_to_bv 64 0x137d68) fc None m (seg_rom asegs)).
Proof.
